module PhluxAIComfyInstaller

const DEFAULT_COMFY_CLI_SPEC = "comfy-cli==1.15.0"
const DEFAULT_COMFYUI_VERSION = "latest"
const DEFAULT_LOCAL_URL = "http://127.0.0.1:8188"
const LAUNCH_EXTRAS = join(
    (
        "--listen 127.0.0.1",
        "--port 8188",
        "--disable-api-nodes",
        "--disable-auto-launch",
    ),
    ' ',
)
const LAUNCHER_MARKER = "Generated by PhluxAI.jl"

function _environment()::Dict{String,String}
    return Dict{String,String}(String(key) => String(value) for
                               (key, value) in ENV)
end

function _env_flag(name::String, default::Bool = false)::Bool
    value = get(ENV, name, nothing)
    isnothing(value) && return default
    normalized = lowercase(strip(String(value)))
    return !(normalized in ("", "0", "false", "no", "off"))
end

function _windows_command_line(values::Vector{String})::String
    quoted = String[]
    for value in values
        escaped = replace(value, '"' => "\"\"")
        push!(quoted, "\"$escaped\"")
    end
    return join(quoted, ' ')
end

function _command(
    executable::String,
    arguments::Vector{String};
    dir::Union{String,Nothing} = nothing,
)::Cmd
    values = String[executable; arguments]
    if Sys.iswindows() && endswith(lowercase(executable), ".cmd")
        command_processor = get(ENV, "COMSPEC", "cmd.exe")
        values = String[
            command_processor,
            "/D",
            "/S",
            "/C",
            _windows_command_line(values),
        ]
    end
    command = Cmd(values)
    return isnothing(dir) ? command : Cmd(command; dir = dir)
end

function _run(
    command::Cmd;
    environment::Dict{String,String},
    description::String,
)::Nothing
    try
        run(setenv(command, environment))
    catch error
        throw(ErrorException(
            "$description failed: " * sprint(showerror, error),
        ))
    end
    return nothing
end

function _read(
    command::Cmd;
    environment::Dict{String,String},
    description::String,
)::String
    try
        return read(setenv(command, environment), String)
    catch error
        throw(ErrorException(
            "$description failed: " * sprint(showerror, error),
        ))
    end
end

function _venv_directory(project_root::String)::String
    return joinpath(project_root, ".venv")
end

function _venv_bin_directory(project_root::String)::String
    return Sys.iswindows() ?
        joinpath(_venv_directory(project_root), "Scripts") :
        joinpath(_venv_directory(project_root), "bin")
end

function _comfy_executable(project_root::String)::String
    executable = Sys.iswindows() ? "comfy.exe" : "comfy"
    path = joinpath(_venv_bin_directory(project_root), executable)
    isfile(path) || error(
        "comfy-cli was installed, but its executable was not found at $path",
    )
    return path
end

function _workspace()::String
    configured = get(ENV, "PHLUXAI_COMFY_WORKSPACE", nothing)
    if !isnothing(configured)
        value = String(strip(configured))
        isempty(value) && error(
            "PHLUXAI_COMFY_WORKSPACE must not be empty.",
        )
        return abspath(normpath(expanduser(value)))
    end

    if Sys.iswindows()
        base = get(
            ENV,
            "LOCALAPPDATA",
            joinpath(homedir(), "AppData", "Local"),
        )
        return joinpath(base, "PhluxAI", "comfy")
    elseif Sys.isapple()
        return joinpath(
            homedir(),
            "Library",
            "Application Support",
            "PhluxAI",
            "comfy",
        )
    end

    data_home = get(
        ENV,
        "XDG_DATA_HOME",
        joinpath(homedir(), ".local", "share"),
    )
    return joinpath(data_home, "PhluxAI", "comfy")
end

function _jupip_environment()::Dict{String,String}
    environment = _environment()
    environment["JUPY_SKIP_JULIA_SETUP"] = "1"
    return environment
end

function _comfy_environment(project_root::String)::Dict{String,String}
    environment = _environment()
    bin_directory = _venv_bin_directory(project_root)
    separator = Sys.iswindows() ? ";" : ":"
    current_path = get(environment, "PATH", "")

    environment["VIRTUAL_ENV"] = _venv_directory(project_root)
    environment["PATH"] = isempty(current_path) ?
        bin_directory : bin_directory * separator * current_path
    environment["COMFY_NO_TELEMETRY"] = "1"
    environment["DO_NOT_TRACK"] = "1"
    environment["COMFY_WHERE"] = "local"
    environment["COMFY_LOCAL_URL"] = DEFAULT_LOCAL_URL
    environment["COMFY_OUTPUT"] = "pretty"
    return environment
end

function _device_option()::String
    configured = lowercase(strip(get(
        ENV,
        "PHLUXAI_COMFY_DEVICE",
        "auto",
    )))
    options = Dict(
        "nvidia" => "--nvidia",
        "amd" => "--amd",
        "m-series" => "--m-series",
        "intel-arc" => "--intel-arc",
        "cpu" => "--cpu",
    )
    configured == "auto" || return get(options, configured) do
        error(
            "PHLUXAI_COMFY_DEVICE must be auto, nvidia, amd, " *
            "m-series, intel-arc, or cpu.",
        )
    end

    if Sys.isapple()
        return Sys.ARCH in (:aarch64, :arm64) ?
            "--m-series" : "--cpu"
    end
    !isnothing(Sys.which("nvidia-smi")) && return "--nvidia"
    (!isnothing(Sys.which("rocm-smi")) ||
     !isnothing(Sys.which("rocminfo"))) && return "--amd"
    (!isnothing(Sys.which("xpu-smi")) ||
     !isnothing(Sys.which("sycl-ls"))) && return "--intel-arc"
    return "--cpu"
end

function _desired_cli_version(
    specification::String,
)::Union{String,Nothing}
    match_value = match(r"^comfy-cli==([^[:space:]]+)$", specification)
    isnothing(match_value) && return nothing
    return String(match_value.captures[1])
end

function _installed_cli_version(
    project_root::String,
)::Union{String,Nothing}
    path = Sys.iswindows() ?
        joinpath(_venv_bin_directory(project_root), "comfy.exe") :
        joinpath(_venv_bin_directory(project_root), "comfy")
    isfile(path) || return nothing
    try
        output = _read(
            _command(
                path,
                ["--skip-prompt", "--version"];
                dir = project_root,
            );
            environment = _comfy_environment(project_root),
            description = "Reading the installed comfy-cli version",
        )
        return strip(output)
    catch
        return nothing
    end
end

function _install_comfy_cli!(
    project_root::String,
    jupip::String,
)::Nothing
    specification = get(
        ENV,
        "PHLUXAI_COMFY_CLI_SPEC",
        DEFAULT_COMFY_CLI_SPEC,
    )
    desired = _desired_cli_version(specification)
    installed = _installed_cli_version(project_root)
    if !isnothing(desired) && installed == desired
        @info "PhluxAI: comfy-cli is already installed" version = installed
        return nothing
    end

    command = _command(
        jupip,
        ["install", "--upgrade", specification];
        dir = project_root,
    )
    _run(
        command;
        environment = _jupip_environment(),
        description = "Installing $specification with jupip",
    )
    return nothing
end

function _comfyui_root(workspace::String)::String
    return joinpath(workspace, "ComfyUI")
end

function _installation_marker(workspace::String)::String
    return joinpath(workspace, ".phluxai-comfy-environment")
end

function _expected_marker(project_root::String)::String
    device = _device_option()
    version = get(
        ENV,
        "PHLUXAI_COMFYUI_VERSION",
        DEFAULT_COMFYUI_VERSION,
    )
    return join(
        (
            "venv=" * abspath(normpath(_venv_directory(project_root))),
            "device=$device",
            "comfyui_version=$version",
            "manager=" * string(
                _env_flag("PHLUXAI_COMFY_INSTALL_MANAGER"),
            ),
            "",
        ),
        '\n',
    )
end

function _marker_matches(
    workspace::String,
    project_root::String,
)::Bool
    marker = _installation_marker(workspace)
    isfile(marker) || return false
    try
        return read(marker, String) == _expected_marker(project_root)
    catch
        return false
    end
end

function _atomic_write(path::String, content::String)::Nothing
    mkpath(dirname(path))
    temporary = tempname(dirname(path))
    try
        open(temporary, "w") do io
            write(io, content)
            flush(io)
        end
        mv(temporary, path; force = true)
    catch
        isfile(temporary) && rm(temporary; force = true)
        rethrow()
    end
    return nothing
end

function _install_comfyui!(
    project_root::String,
    comfy::String,
    workspace::String,
)::Nothing
    mkpath(workspace)
    environment = _comfy_environment(project_root)
    comfyui_root = _comfyui_root(workspace)
    installed = isfile(joinpath(comfyui_root, "main.py"))
    needs_restore = installed && !_marker_matches(
        workspace,
        project_root,
    )

    if installed && !needs_restore
        @info "PhluxAI: ComfyUI is already configured" workspace
        return nothing
    end

    if ispath(comfyui_root) && !installed
        isempty(readdir(comfyui_root)) || error(
            "ComfyUI target exists but is not a valid installation: " *
            comfyui_root,
        )
        rm(comfyui_root; recursive = true, force = true)
    end

    version = get(
        ENV,
        "PHLUXAI_COMFYUI_VERSION",
        DEFAULT_COMFYUI_VERSION,
    )
    device = _device_option()
    arguments = String[
        comfy,
        "--skip-prompt",
        "--where",
        "local",
        "--workspace",
        comfyui_root,
        "install",
        "--version",
        version,
        device,
    ]
    _env_flag("PHLUXAI_COMFY_INSTALL_MANAGER") ||
        push!(arguments, "--skip-manager")
    needs_restore && push!(arguments, "--restore")

    cuda_version = strip(get(ENV, "PHLUXAI_COMFY_CUDA_VERSION", ""))
    if device == "--nvidia" && !isempty(cuda_version)
        append!(arguments, ("--cuda-version", cuda_version))
    end

    rocm_version = strip(get(ENV, "PHLUXAI_COMFY_ROCM_VERSION", ""))
    if device == "--amd" && !isempty(rocm_version)
        append!(arguments, ("--rocm-version", rocm_version))
    end

    _env_flag("PHLUXAI_COMFY_FAST_DEPS") &&
        push!(arguments, "--fast-deps")

    action = needs_restore ?
        "Restoring ComfyUI dependencies" : "Installing ComfyUI"
    _run(
        _command(
            first(arguments),
            arguments[2:end];
            dir = project_root,
        );
        environment,
        description = action,
    )
    isfile(joinpath(comfyui_root, "main.py")) || error(
        "ComfyUI installation completed without creating $comfyui_root",
    )
    _atomic_write(
        _installation_marker(workspace),
        _expected_marker(project_root),
    )
    return nothing
end

function _configure_comfy!(
    project_root::String,
    comfy::String,
    comfyui_root::String,
)::Nothing
    environment = _comfy_environment(project_root)
    commands = (
        (
            _command(
                comfy,
                [
                    "--skip-prompt",
                    "tracking",
                    "disable",
                ];
                dir = project_root,
            ),
            "Disabling comfy-cli telemetry",
        ),
        (
            _command(
                comfy,
                [
                    "--skip-prompt",
                    "set-default",
                    comfyui_root,
                    "--launch-extras",
                    LAUNCH_EXTRAS,
                ];
                dir = project_root,
            ),
            "Configuring the default ComfyUI workspace",
        ),
        (
            _command(
                comfy,
                [
                    "--skip-prompt",
                    "set-default",
                    "--where",
                    "local",
                ];
                dir = project_root,
            ),
            "Configuring local-only comfy-cli routing",
        ),
    )

    for (command, description) in commands
        _run(command; environment, description)
    end
    return nothing
end

function _launcher_directory()::String
    if Sys.iswindows()
        local_app_data = get(
            ENV,
            "LOCALAPPDATA",
            joinpath(homedir(), "AppData", "Local"),
        )
        return joinpath(local_app_data, "Jupy", "bin")
    end
    return get(
        ENV,
        "JUPY_BIN_DIR",
        joinpath(homedir(), ".local", "bin"),
    )
end

function _backup_existing(path::String)::Nothing
    !(ispath(path) || islink(path)) && return nothing
    if isfile(path)
        content = try
            read(path, String)
        catch
            ""
        end
        occursin(LAUNCHER_MARKER, content) && return nothing
    end

    backup = path * ".pre-phluxai"
    counter = 1
    while ispath(backup) || islink(backup)
        counter += 1
        backup = path * ".pre-phluxai.$counter"
    end
    mv(path, backup; force = true)
    @info "PhluxAI: preserved existing comfy launcher" path backup
    return nothing
end

function _shell_quote(value::String)::String
    return "'" * replace(value, "'" => "'\"'\"'") * "'"
end

function _install_launcher!(
    project_root::String,
    comfy::String,
)::String
    directory = _launcher_directory()
    mkpath(directory)
    venv = _venv_directory(project_root)
    venv_bin = _venv_bin_directory(project_root)

    if Sys.iswindows()
        launcher = joinpath(directory, "comfy.cmd")
        _backup_existing(launcher)
        content = join(
            (
                "@echo off",
                "rem $LAUNCHER_MARKER",
                "set \"VIRTUAL_ENV=$venv\"",
                "set \"PATH=$venv_bin;%PATH%\"",
                "set \"COMFY_NO_TELEMETRY=1\"",
                "set \"DO_NOT_TRACK=1\"",
                "set \"COMFY_WHERE=local\"",
                "set \"COMFY_LOCAL_URL=$(DEFAULT_LOCAL_URL)\"",
                "\"$comfy\" %*",
                "",
            ),
            "\r\n",
        )
        _atomic_write(launcher, content)
        return launcher
    end

    launcher = joinpath(directory, "comfy")
    _backup_existing(launcher)
    content = join(
        (
            "#!/bin/sh",
            "# $LAUNCHER_MARKER",
            "export VIRTUAL_ENV=$(_shell_quote(venv))",
            "export PATH=$(_shell_quote(venv_bin)):\$PATH",
            "export COMFY_NO_TELEMETRY=1",
            "export DO_NOT_TRACK=1",
            "export COMFY_WHERE=local",
            "export COMFY_LOCAL_URL=$(DEFAULT_LOCAL_URL)",
            "exec $(_shell_quote(comfy)) \"\$@\"",
            "",
        ),
        '\n',
    )
    _atomic_write(launcher, content)
    chmod(launcher, 0o755)
    return launcher
end

function _sync_requirements!(
    project_root::String,
    jupip::String,
)::Nothing
    command = _command(
        jupip,
        ["freeze"];
        dir = project_root,
    )
    frozen = _read(
        command;
        environment = _jupip_environment(),
        description = "Capturing the Jupy Python environment",
    )
    content = isempty(frozen) || endswith(frozen, '\n') ?
        frozen : frozen * "\n"
    _atomic_write(joinpath(project_root, "requirements.txt"), content)
    return nothing
end

"""Install comfy-cli and configure a local ComfyUI runtime."""
function install_comfy!(
    project_root::AbstractString;
    jupip_path::Union{AbstractString,Nothing} = nothing,
)::NamedTuple
    root = abspath(normpath(String(project_root)))
    isfile(joinpath(root, "Project.toml")) || error(
        "No Project.toml was found at the PhluxAI project root: $root",
    )

    jupip = if isnothing(jupip_path)
        resolved = Sys.which("jupip")
        isnothing(resolved) && error(
            "jupip is not installed; run install_jupy! first.",
        )
        String(resolved)
    else
        String(jupip_path)
    end
    isfile(jupip) || error("jupip does not exist at $jupip")

    _install_comfy_cli!(root, jupip)
    comfy = _comfy_executable(root)
    workspace = _workspace()
    _install_comfyui!(root, comfy, workspace)
    comfyui_root = _comfyui_root(workspace)
    _configure_comfy!(root, comfy, comfyui_root)
    launcher = _install_launcher!(root, comfy)
    _sync_requirements!(root, jupip)

    version = strip(_read(
        _command(
            comfy,
            ["--skip-prompt", "--version"];
            dir = root,
        );
        environment = _comfy_environment(root),
        description = "Reading the comfy-cli version",
    ))
    @info(
        "PhluxAI: local ComfyUI is configured",
        comfy_cli_version = version,
        comfy = comfy,
        launcher = launcher,
        workspace = comfyui_root,
        data_root = workspace,
    )
    @info "Install an image model with" command =
        "comfy model download --url <MODEL_URL> " *
        "--relative-path models/checkpoints"

    return (
        comfy = comfy,
        launcher = launcher,
        workspace = comfyui_root,
        data_root = workspace,
        version = version,
    )
end

export install_comfy!

end # module PhluxAIComfyInstaller
